			assertEquals(originalInventory, controlInventory,
					"Mandatory factors/constants, FILTER/OPTIONAL scopes, projection and aggregates must match");
			phase = "prepare-all-contestants";
			// Freeze every selected plan before executing any contestant or collecting learned feedback.
			for (String mode : modes) {
				phase = "prepare-selected-" + mode;
				System.setProperty(MODE, mode);
				plans.add(new NamedPlan("selected-" + mode, state.selected()));
			}
			phase = "prepare-written-control";
			NamedPlan control = new NamedPlan("written-control", state.control(controlText));
			plans.add(control);
			phase = "capture-owned-provenance";
