			Access actual = expected.access();
			assertTrue(actual.requests() <= bounds.requests(), "Control request count exceeds source-derived bound");
			assertTrue(actual.matched() <= bounds.matched(), "Control matches exceed source-derived bound");
			assertTrue(actual.scanned() <= bounds.scanned(), "Control scans exceed source-derived bound");
			// Selected vectors are evidence, not a new pass condition or an order waiver.
			phase = "completed";
